node <<'NODE'
const fs = require('node:fs');
const crypto = require('node:crypto');
const zlib = require('node:zlib');
const diff = require('diff');
const baselinePath = 'docs/remediation/design/W37.04/baseline.json';
const baselineBytes = fs.readFileSync(baselinePath);
const baseline = JSON.parse(baselineBytes);
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const artifacts = [], deltas = [], warningMap = {};
for (const entry of baseline.owned) {
  const before = zlib.gunzipSync(Buffer.from(entry.content_gzip_base64, 'base64')).toString('utf8');
  const after = fs.readFileSync(entry.path, 'utf8');
  if (sha(before) !== entry.sha256) throw new Error('Admission content hash mismatch: ' + entry.path);
  const patch = diff.createPatch(entry.path, before, after, 'admission', 'W37.04', { context: 3 });
  if (diff.applyPatch(before, patch) !== after || diff.applyPatch(after, diff.reversePatch(patch)) !== before) throw new Error('Delta is not reversible: ' + entry.path);
  artifacts.push({ path: entry.path, sha256: sha(after) });
  deltas.push({ path: entry.path, before_sha256: sha(before), after_sha256: sha(after), unified_diff: patch, applied_and_reversed: true });
  let oldLine = 1, newLine = 1; const map = {};
  for (const part of diff.diffLines(before, after)) {
    const n = part.count;
    if (!part.added && !part.removed) for (let i = 0; i < n; i++) map[newLine + i] = oldLine + i;
    if (!part.added) oldLine += n;
    if (!part.removed) newLine += n;
  }
  warningMap[entry.path] = map;
}
const owned = new Set(baseline.owned.map(p => p.path));
const unchanged = baseline.pins.filter(p => !owned.has(p.path));
const mismatches = unchanged.filter(p => sha(fs.readFileSync(p.path)) !== p.sha256);
console.log(JSON.stringify({ captured_at: new Date().toISOString(), baseline: { path: baselinePath, sha256: sha(baselineBytes) }, artifacts, artifact_digest: sha(JSON.stringify(artifacts)), deltas, unowned_pins: { checked: unchanged.length, mismatches }, warning_map: warningMap }));
NODE

